# -*- coding: utf-8 -*-
"""English translations, batch 3 (40 figures)."""
EN = {
"撒拉": dict(lesson="The patience of faith",
 summary="Abraham's wife, who waited a lifetime for God's promise; she once laughed in unbelief, and at last bore Isaac at ninety.",
 witness="Sarah waited decades. In the tent she heard the angel say she would bear a son in a year, and she laughed—a bitter laugh. But God did not cancel the promise because of her unbelief. She became Isaac's mother and entered the hall of faith in Hebrews 11, counted as one who deemed God faithful.",
 follow=["Following her husband's call to leave their homeland, a faithful companion","Believing in the end, and bearing the son of promise","Called a model of submission in the New Testament"],
 caution=["Substituting Hagar for herself, helping her husband bear a son by human means, causing long family conflict","Laughing in unbelief at the promise, then denying she had laughed"],
 applications=["Fight bitterness in long waiting; don't let waiting turn into resentment","Don't help God fulfill His plan by your own methods","Keep committing even when the promise is unfulfilled","Admit your unbelief, yet still choose to keep following","Is there a promise in waiting that has bred bitterness in you? Bring it to God"],
 prayer="Lord, Sarah's waiting held laughter, tears, mistakes, and at last faith. I too am waiting for Your promise. Help me not to replace Your will with my own methods, nor let bitterness replace faith. Amen."),
"亚伦": dict(lesson="The responsibility of holy service",
 summary="The first high priest, co-worker with Moses; yet under pressure he made the golden calf—a warning about compromise.",
 witness="Aaron was God's chosen high priest, with a very high calling. But when Moses delayed coming down and the people pressured him, he compromised and made the golden calf. His excuse—I threw the gold into the fire and out came this calf—is the most absurd cover-up of responsibility.",
 follow=["Co-working with Moses, a key partner in God's work","Chosen by God as the first high priest","Faithfully assisting Moses on many occasions"],
 caution=["Compromising under the people's pressure, making the golden calf","Covering his dereliction with an absurd excuse","Insufficient spiritual discipline of his sons"],
 applications=["Hold God's standard under pressure, not compromising for what's popular","Bear a leader's responsibility, not shifting it to circumstances or people","With spiritual standing, be all the more watchful against weakness","Honestly admit your failures, without excuses","Is there something you compromised on today because of pressure?"],
 prayer="Lord, Aaron's compromise reminds me: the higher the calling, the more I must depend on You. Help me not to compromise under pressure, and to be humbler when I have standing. When I fail, let me confess honestly rather than make excuses. Amen."),
"米利暗": dict(lesson="The cost of a leader's pride",
 summary="A prophetess who led the women in praise, but out of jealousy and pride criticized Moses and was struck with leprosy—a warning about pride after success.",
 witness="Miriam was a truly gifted prophetess; leading the women in praise at the Red Sea was a glorious moment. But after success she began to criticize God's servant on an outward pretext (Moses' Cushite wife)—the root being jealousy and pride. God disciplined her at once.",
 follow=["Having a genuine prophetic gift, leading the women in praise","A key female leader in the exodus history"],
 caution=["Pride and jealousy arising after success","Criticizing God's appointed leader on a surface pretext","Seeking recognition above her station"],
 applications=["In moments of success, be especially watchful for pride","Before criticizing others, check whether your motive is jealousy","Respect the authority God appoints, even when you disagree with some decisions","A true gift needs no belittling of others to shine","Is any criticism today out of jealousy rather than real care?"],
 prayer="Lord, Miriam's story is the warning most needed after success. Help me be humbler in success, and check my motives before criticizing others. Let my gift serve You, not my pride. Amen."),
"底波拉": dict(lesson="Courageous leadership",
 summary="A prophetess and judge who stepped forward in an age when men shrank back, leading Israel to victory—a model of courageously answering God's call.",
 witness="Deborah lived in the most chaotic age of the judges. God chose a woman to lead—not because there were no men, but because she was willing to answer the call. When Barak dared not go to battle alone, she went with him. Courage is not the absence of fear, but acting in spite of it.",
 follow=["Courageously answering God's call when men shrank back","Leading the people with prophetic authority and a judge's wisdom","Leading the whole nation out of oppression"],
 caution=[],
 applications=["When God calls, don't hesitate over gender, age, or others' reluctance","Use spiritual authority to encourage those around you who lack courage","Be a voice of stability and wisdom amid chaos","Is there something you should do but haven't, because you're waiting for someone else to move first?","Sometimes God's call falls to us precisely because others are unwilling"],
 prayer="Lord, Deborah's story shows me: You call those willing to obey, whatever their background. When those around me shrink back, give me Deborah's courage to say: I am willing. Amen."),
"基甸": dict(lesson="Victory over many by God's power",
 summary="God used 300 men to rout 135,000 Midianites, showing His power made perfect in human weakness; yet in old age Gideon made a golden ephod.",
 witness="Gideon first appears hiding from the enemy in a winepress, and God calls him 'mighty warrior.' He asked God to confirm three times before he dared set out. Yet God insisted on reducing 32,000 to 300, for one reason: so Israel could not credit themselves. As expected, the 300 won.",
 follow=["Still answering God's call in his weakness","Fully obeying God's strange strategy","Leading the people into forty years of peace"],
 caution=["Repeatedly asking God for signs, showing weak faith","Refusing kingship yet casting a golden ephod that became an idol","Weak family management, later causing a blood feud"],
 applications=["God deliberately uses weak instruments so His power shows more clearly","When God's method seems absurd, still obey and carry it out","In success, give glory to God rather than accept people's worship","Faith must be built on God's word, not only on feelings","Is there something you feel too weak for, that is exactly what God wants to use?"],
 prayer="Lord, You called Gideon 'mighty warrior' while he hid in a winepress. You see me the same way—not by my present weakness, but by what You can accomplish. Help me, in my weakness, to still be willing to be used by You. Amen."),
"参孙": dict(lesson="The cost of failed self-discipline",
 summary="A Nazirite called from the womb with supernatural strength, who lost everything through lust and pride—a warning that spiritual gifting needs character.",
 witness="Samson had a wonderful gift—unmatched strength. But his life was a record of self-indulgence: marrying a foreign wife, seeking a prostitute, loving Delilah. His strength was never used for the redemptive mission God called him to. In the end he was attacked at his weakest point. Gifting is not character.",
 follow=["Having a real spiritual calling and supernatural strength","Crying out to God at the final moment of life, and God still answered"],
 caution=["Using God's gift for personal lust and revenge","Ignoring the Nazirite requirement of separation","Blind to the warning pattern with Delilah","Pride that he could stay in dangerous relationships indefinitely"],
 applications=["Know where your greatest weakness lies, and build defenses","Don't enter situations that repeatedly make you fall","The greater the gift, the higher the demand on character","After sinning, don't give up—you can still cry out to God","Don't let lust decide your key relationship choices"],
 prayer="Lord, Samson's story is the truest warning for me. I too have my Delilah—the place where I fall again and again. Help me recognize it, build defenses, and not let my gift be disgraced by a failure of character. Amen."),
"波阿斯": dict(lesson="Character and compassion",
 summary="A wealthy kinsman-redeemer who, by character, kindness, and faithfulness, married Ruth—a model that character determines influence.",
 witness="The first time Boaz saw Ruth, he ordered his servants to leave extra grain for her and not to shame her. He did not wait for Ruth to ask, but expressed care by his own character. True character is choosing to treat the weak well even when no one requires it.",
 follow=["Treating the foreigner and the vulnerable well by his own initiative","Faithfully taking up the role of kinsman-redeemer per the law's duty","Respecting Ruth's dignity and agency in his pursuit"],
 caution=[],
 applications=["Build relationships by character, not flattery","Care for the vulnerable around you proactively, not waiting for them to ask","When you have the means, take up the responsibility you owe","Your character shows most truly when no one requires it","Who can you treat kindly today, with no reason needed?"],
 prayer="Lord, Boaz's character is what I want: proactive, kind to the weak, faithfully responsible. Let my character choose good even when no one requires it, and bear responsibility when I have the means. Amen."),
"哈拿": dict(lesson="The power of prayer",
 summary="Suffering long from barrenness, she wept and prayed; God heard, and she bore the prophet Samuel—the deepest model of genuine prayer.",
 witness="Hannah's prayer was not elegant words, but heartbroken tears. She wept aloud in the temple, and Eli thought she was drunk. But God saw the anguish of her heart. True prayer is not a performance for people, but bringing your deepest pain to God.",
 follow=["Bringing her deepest pain honestly to God","Faithfully keeping her vow after receiving the promise","Giving the child she received back to God—the deepest faith"],
 caution=["In her initial anguish there may have been an element of self-pity"],
 applications=["You don't need elegant words—bring your real pain to God","Don't perform in prayer; only be real","After God hears, keep your promise","Give back to God what is most precious to you","Is there something too painful that you've never spoken to God?"],
 prayer="Lord, Hannah's prayer is the truest prayer. Let me too learn to bring my heartbreak before You—not performing elegantly, but pouring out honestly. Thank You for hearing heartbroken prayers. Amen."),
"扫罗": dict(lesson="The cost of pride and disobedience",
 summary="Israel's first king, rejected by God for pride and disobedience—the most profound living lesson that obedience is better than sacrifice.",
 witness="Saul began humbly—hiding among the baggage, saying, who am I? But once he had royal power, he began to act on his own. He offered sacrifices presumptuously at Gilgal; he kept the spoil in the Amalekite war—each time with a good reason. But God said: to obey is better than sacrifice.",
 follow=["A humble posture at the start","Real leadership and military ability"],
 caution=["Disobeying God's command under pressure, acting on his own","Covering disobedience with religious acts (sacrifice)","When confronted, making excuses instead of confessing","Letting jealousy of David grow into a manhunt"],
 applications=["Obey God's command even when you don't understand—without discount","When confronted with error, confess honestly rather than make excuses","Don't let jealousy grow in your heart; deal with it early","The higher your standing and ability, the more you need the humility of obedience","Is there a command of God you keep finding reasons not to obey?"],
 prayer="Lord, Saul's tragedy was not one great sin, but a series of small disobediences piling up. Help me not to discount Your will in small things, nor cover disobedience with sacrifice. To obey is better than sacrifice—let this be the rule of my life. Amen."),
"亚哈": dict(lesson="The danger of bad influence",
 summary="The most evil king of the north; influenced by his wife Jezebel he introduced Baal worship and seized Naboth's vineyard—yet after the prophet's warning he humbled himself, and astonishingly God deferred judgment.",
 witness="He did more evil than the kings before him. But when Elijah delivered God's judgment, he tore his clothes, wore sackcloth, and fasted. God said: do you see how Ahab humbles himself before Me? Even partial humility, God noticed.",
 follow=[],
 caution=["Letting a spouse's straying lead him away from God","Seizing by power what others rightly owned","Only brief humility before the prophet's warning, not real change"],
 applications=["Is the person closest to you drawing you toward God or away?","God's response to Ahab: even imperfect humility, God sees","Examine: do I have a 'want it, take it' pattern of control?","When facing the truth, how will you respond to God's word?"],
 prayer="Lord, even Ahab's partial humility You saw. Help me not to use the straying of those close to me as an excuse to stray from You, and to respond truly when the prophet's word comes. Amen."),
"约沙法": dict(lesson="Seeking God in crisis",
 summary="A good king of Judah; when a coalition of three nations pressed in, he proclaimed a fast and led the whole nation in prayer, and God fought for them; yet he also allied with the evil king Ahab and nearly died.",
 witness="His prayer: O God, we do not know what to do, but our eyes are on You. He did not pretend to have a plan, but declared dependence. God's reply: the battle is not yours, but God's.",
 follow=["His first response in crisis was to proclaim a fast and pray","Admitting helplessness, fixing his eyes only on God","Leading the whole nation to humble themselves before God"],
 caution=["Allying with the evil king Ahab and nearly dying","Lacking, at certain key moments, the discernment to recognize the wicked"],
 applications=["In crisis, what is your first response—meetings and phone calls, or prayer?","Say honestly to God: I don't know what to do—this is faith, not weakness","Bring to God today a situation you have no idea how to handle"],
 prayer="Lord, Jehoshaphat said: our eyes are on You. Help me come before You in the same honest posture when I'm most at a loss. The battle is Yours, not mine. Amen."),
"希西家": dict(lesson="Deliverance through prayer",
 summary="One of Judah's most devout kings; he spread Sennacherib's threatening letter before God and prevailed; he also prayed in mortal illness and was healed—a real case of prayer's miracles.",
 witness="With the Assyrian army at the gates, Hezekiah went into the temple and spread the letter before God: incline Your ear and hear; open Your eyes and see. Then God destroyed 185,000 Assyrian soldiers in one night. Bring the real problem before God, and God Himself acts.",
 follow=["Spreading a real threat directly before God","Praying for extended life in mortal illness, and God responded","Actively removing idols throughout the nation"],
 caution=["After being granted extra years, showing off his treasury to the Babylonian envoys","Pride in his later years, a haughty heart"],
 applications=["Have you spread before God the threat that frightens you?","Bring the actual problem to God concretely, not abstractly","After success, beware the urge to show off—this is where Hezekiah lost"],
 prayer="Lord, Hezekiah spread the threatening letter before You. Help me bring the thing that most troubles me today before You too—telling You concretely and honestly—then wait for Your response. Amen."),
"何西阿": dict(lesson="God's love that never gives up",
 summary="Called by God to marry the unfaithful Gomer, he lived out through the pain of his own marriage God's never-abandoning love for rebellious Israel; his life was a living parable.",
 witness="Gomer left him, yet he went to the slave market and bought her back. God said: go again, love a woman loved by another and an adulteress, as the LORD loves the Israelites. God's love is built not on the other's response, but on God's character.",
 follow=["Willingly using his own broken marriage as a 'living parable,' redeeming his betraying wife from the slave market (Hos 3:1-2), living out God's pursuing love for sinners","Faithfully proclaiming 'how can I give you up' even at Israel's lowest spiritual point (Hos 11:8)","Declaring 'I desire mercy, not sacrifice,' bringing faith from outward ritual back to truly knowing God (Hos 6:6)"],
 caution=[],
 applications=["God's love actively pursues, even when the other keeps turning away","Is there a relationship you feel is no longer worth loving? Hosea says: go love anyway","God is pursuing you—not waiting for you to change first before coming to Him","Is there someone you need to love more actively today, even without a response?"],
 prayer="Lord, Hosea's love is a mirror of Yours—active, persistent, not stopping at the other's betrayal. Help me love the hard-to-love with such love, because You first loved me this way. Amen."),
"末底改": dict(lesson="Not yielding to pressure",
 summary="Esther's guardian, who refused to bow to Haman and exposed a plot to kill the king; his refusal to compromise became the start of a chain reaction that saved a whole people.",
 witness="Everyone bowed to Haman; only Mordecai would not. His reason was not arrogance, but that his worship of God allowed him to bow to no one. One man's faithfulness changed the destiny of a whole people.",
 follow=["Not bowing to power under social pressure","Raising Esther and guiding her toward God's purpose","Exposing the truth, even when exposure brought danger"],
 caution=[],
 applications=["Is there something you refuse to compromise on when everyone else does?","Mordecai's refusal triggered the whole redemption story—faithfulness is sometimes the start of a chain reaction","Is there a small 'refusal to bow' you need to hold today?","Risk for others' good—Mordecai's exposure was for the king, not himself"],
 prayer="Lord, Mordecai would not bow when everyone else did. Help me, when pressure is greatest, to discern what I must never compromise, and then to stand firm. Amen."),
"吕底亚": dict(lesson="Generous hospitality, the start of the European church",
 summary="A successful dealer in purple cloth in Philippi; God opened her heart, she and her household were baptized, and she at once urged Paul's group to stay in her home—the cradle of the first church in Europe.",
 witness="God opened her heart to pay attention to what Paul said. Then she acted at once: her whole household was baptized, and she urged the apostles to stay in her home. Spiritual openness and an open home went together—the heart opened, and the home opened too.",
 follow=["Responding at once with action after her heart was opened by God","Opening her resources and home as a base for God's kingdom service","Proactively hosting the messengers, not waiting to be asked"],
 caution=[],
 applications=["God opened her heart—has your heart been opened by God to notice what He is saying?","Spiritual openness and an open home are linked—can your home also become a tool for God's kingdom?","Lydia was a successful businesswoman—worldly success and spiritual commitment don't conflict","Is there a resource or space you can proactively open to serve God's kingdom today?"],
 prayer="Lord, Lydia's heart was opened by You, and her home opened too. Open my heart to notice what You are saying, then let me open all I have to Your kingdom. Amen."),
"多加": dict(lesson="A life of loving service and good works",
 summary="A disciple in Joppa, full of good works and acts of charity; when she died, the widows wept holding the garments she had made—her service left tangible, named traces.",
 witness="The widows wept, holding the clothes Dorcas had sewn—this was not abstract service, but real needle, thread, and time. Her life was remembered for concrete love.",
 follow=["Serving those in need around her with concrete action","Serving quietly, not measuring worth by fame or status","Turning faith into the real giving of needle, thread, time, and goods"],
 caution=[],
 applications=["Dorcas' service left garments—does your service leave concrete, visible traces too?","Full of good works: is there a specific good deed you've long wanted to do but kept delaying?","She served widows—who around you needs real help, not just comforting words?","Do one concrete good deed today, with no one needing to know"],
 prayer="Lord, Dorcas served the widows with needle and thread and time. Help me turn faith into concrete action too, leaving real traces of love. Amen."),
"哥尼流": dict(lesson="God accepts all who seek Him",
 summary="A Roman centurion who feared God, gave generously to the people, and prayed constantly; his prayer was remembered by God, who sent Peter to preach to him and his household—a historic moment of Gentiles receiving the Spirit.",
 witness="The angel told Cornelius: your prayers and your gifts have come up as a memorial before God. Without full knowledge of the gospel, he sought God with reverence and generosity, and God remembered him. God seeks those who truly seek Him.",
 follow=["Praying constantly with a God-fearing heart, not letting his rank dull his spiritual hunger","Living out faith through giving, not just inner belief","When God opened the door, immediately inviting those around him to receive the gospel together"],
 caution=[],
 applications=["Your prayers and giving are remembered by God—what is your devout way of life today?","Cornelius was not a Jew, yet God accepted him—God's door is open to all who truly seek","When God answered, he at once gathered family and friends—are you bringing those around you to God?","Do one concrete thing today in both prayer and giving"],
 prayer="Lord, Cornelius' prayers and giving were remembered by You. Help me seek You too with a reverent, generous way of life, trusting that You see every heart that truly seeks You. Amen."),
"尼哥底母": dict(lesson="The path of faith from night to the open",
 summary="A Pharisee who came to Jesus by night, and in the end openly helped bury Him.",
 witness="Nicodemus' life holds both an example to follow and a warning to heed. Faith must move from the private to the open.",
 follow=["A Pharisee and council member, yet sincerely visiting Jesus by night, humbly asking about being born again","In the council, speaking up for Jesus: 'does our law condemn a man without first hearing him?' (John 7:51)","After Jesus was crucified, openly bringing a hundred pounds of myrrh and aloes to bury Him—faith moving from hidden to open (John 19:39)"],
 caution=["At first, out of fear of his peers and his status, daring to come to Jesus only privately at night","Stopping at a literal understanding of spiritual rebirth ('how can a man be born when he is old?'), slow to grasp the things of the Spirit"],
 applications=["Is your faith still 'at night'—only private, not daring to identify with the Lord openly?","Rebirth is the Spirit's work, not by works or knowledge; ask God today for this life from above","Like Nicodemus, let your faith move step by step from hidden to open commitment"],
 prayer="Lord, let my faith, step by step, identify with You more openly and bravely. Amen."),
"马可": dict(lesson="Restoration after failure",
 summary="He abandoned the first mission halfway, but was later restored and wrote the Gospel of Mark.",
 witness="Mark's life holds both an example to follow and a warning to heed. Failure is not the end, but a new beginning.",
 follow=["After his first failure, not staying down but re-engaging in service","Called by Paul in his later years 'useful to me for ministry,' regaining trust (2 Tim 4:11)","Writing the Gospel of Mark, the earliest written gospel record"],
 caution=["On the first missionary journey, shrinking back midway and leaving Paul and Barnabas to return to Jerusalem (Acts 13:13)","This withdrawal later became the spark of the dispute and parting between Paul and Barnabas (Acts 15:37-39)"],
 applications=["One withdrawal is not your end—the Gospel of Mark is the witness of a failure restored","Be like Barnabas, giving a second chance to those who once failed","Is there something you abandoned halfway that God is inviting you to return and finish?"],
 prayer="Lord, let me believe my failure is not Your final verdict on me. Amen."),
"玛土撒拉": dict(lesson="Life is in God's hands",
 summary="The longest-lived man in history, 969 years; son of Enoch, the year of the flood was the year of his death—through his lifetime God still waited and was patient.",
 witness="Methuselah's lifespan itself was a sign of God's patience and grace—the year he died, the flood came. God's timetable is interwoven with human life; no day is by chance.",
 follow=["Accepting that life's length and timing are in God's hands","Holding to faith through long years, not slackening because time is long","Recognizing God's kindness in waiting and patience"],
 caution=[],
 applications=["Long life does not equal meaning; faithful years are true life","God waited through his 969 years—what is God waiting for in your life today?","Don't postpone repentance or obedience just because life still seems long","What is one meaningful thing to do today?"],
 prayer="Lord, Methuselah's life tells me You are patiently waiting. Help me not to slacken because the years are long, but to live faithfully every day You give me. Amen."),
"以扫": dict(lesson="Despising spiritual blessing",
 summary="He sold his birthright for a bowl of red stew.",
 witness="Esau's story is a real warning about despising spiritual blessing. Short-sighted satisfaction is more dangerous than long-term spiritual value.",
 follow=["Years later, laying down his hatred and running to embrace Jacob, reconciling with him (Gen 33:4)"],
 caution=["Despising and selling his birthright for a bowl of red stew, sacrificing long-term spiritual blessing for an immediate appetite","'I am about to die; of what use is the birthright to me?'—despising God's promise with realism (Heb 12:16 calls him godless)","After losing the blessing, weeping bitterly but unable to recover it—too late to repent"],
 applications=["Have you sacrificed long-term spiritual good for immediate satisfaction (pleasure, comfort, face)?","Don't make major decisions when hungry, tired, or low—that is just how Esau lost his blessing","A spiritual birthright, once despised, is hard to recover; treasure today the calling and place God gives you"],
 prayer="Lord, let me not despise the spiritual blessing You give me for the sake of present desire. Amen."),
"利百加": dict(lesson="God guides marriage, but trickery must not replace faith",
 summary="Isaac's wife, wondrously guided by God to marry Isaac, but later favored Jacob and manipulated the outcome.",
 witness="Rebekah's life holds both an example to follow and a warning to heed. God can guide a marriage, but trickery must not replace faith.",
 follow=["Diligently drawing water for the servant and his ten camels at the well, prepared by God as Isaac's wife through her kindness and diligence (Gen 24)","Facing an unknown marriage, resolutely answering 'I will go,' leaving her home by faith"],
 caution=["Favoring the younger son Jacob, scheming to help him steal the blessing Isaac meant for Esau","Inciting Jacob to deceive his blind father, trying to 'fulfill' God's prophecy by human means","The price of the scheme: she never saw her beloved Jacob again (he fled to Haran for years)"],
 applications=["God's promise does not need you to 'help' fulfill it with lies—Rebekah's scheme brought family separation","Parental favoritism plants lasting rifts among children","Before God's promise, choose trust and waiting rather than manipulating the outcome"],
 prayer="Lord, let me trust Your guidance rather than help fulfill Your will by human trickery. Amen."),
"约基别": dict(lesson="Bravely protecting life",
 summary="Moses' mother; under Pharaoh's command to kill all Hebrew baby boys, she hid the infant Moses three months, then wove a reed basket and placed him in the Nile, entrusting her son to God by faith; she was later hired to nurse her own child.",
 witness="She placed her child in a reed basket—not a desperate abandonment, but a committal of faith. God wondrously had Pharaoh's daughter pick up Moses, and had Jochebed hired to nurse her own son. Her act of faith became the starting point of God's saving history for Israel.",
 follow=["Protecting an entrusted life by faith even in a life-threatening extremity","Finding God's way out within constraints, with creativity and courage","Placing what was most precious in God's hands, even when it seemed dangerous"],
 caution=[],
 applications=["Jochebed putting her son in the river was faith, not despair—can you place what's most precious in God's hands now?","Protecting life under great pressure—what life do you need to safeguard today?","God let her nurse her own child—obeying God often brings restoration in unexpected ways","Is there something you've been clinging to that you can entrust to God today?"],
 prayer="Lord, Jochebed placed her most precious son in the river, entrusting him to You. Help me too, in the hardest places, to entrust what matters most to Your hands, trusting Your protection over my own grip. Amen."),
"西坡拉": dict(lesson="Becoming God's channel across cultural difference",
 summary="Moses' wife, who at a crucial moment circumcised their son and saved Moses' life.",
 witness="Zipporah's life holds both an example to follow and a warning to heed. Even across cultural difference she could become a channel of God's plan.",
 follow=["At the critical moment when God sought to kill Moses, decisively circumcising her son and saving her husband's life (Exod 4:24-26)","A keen spiritual judgment about God's covenant with the family, acting decisively at the crucial moment"],
 caution=["Beforehand, seemingly delaying and not keeping the covenant of circumcision God appointed, nearly bringing disaster","'Surely you are a bridegroom of blood to me'—revealing tension and displeasure over her husband's mission and covenant"],
 applications=["Delayed spiritual responsibilities at home (children's faith, unfinished obedience) can become hidden dangers—deal with them today","In crisis, have Zipporah's decisiveness—immediately do what God commands","Bring tensions over faith and mission within marriage to God to resolve, rather than letting them pile up"],
 prayer="Lord, let me obey Your will even across different backgrounds. Amen."),
"俄陀聂": dict(lesson="The first judge prevailed by the Spirit",
 summary="The first deliverer of Israel's era of judges, Caleb's nephew; the Spirit of the LORD came upon him, he went to war against Cushan-rishathaim and won, giving the land peace for forty years.",
 witness="Judges describes him: the Spirit of the LORD came upon him, and he judged Israel. The Spirit was the source of his victory, not his own ability. This is the first pattern of the era of judges, and the core lesson of the whole book.",
 follow=["Relying on the Spirit of the LORD rather than his own strength to go to war","Bravely answering when God called, not declining because the enemy was strong","Watching over the people after victory, bringing lasting peace"],
 caution=[],
 applications=["Othniel's victory began with the Spirit coming upon him—in what do you need to wait for the Spirit's power rather than charging ahead on your own?","The first judge was holy and faithful—a good start is key to setting the right pattern","What is your 'Cushan-rishathaim' today? Is there a spiritual battle you keep avoiding?","Relying on the Spirit is not passive waiting, but acting under the Spirit's guidance"],
 prayer="Lord, Othniel prevailed in the power of the Spirit. Help me, facing spiritual battles, first to wait for Your Spirit, then to act bravely in Your power rather than my own. Amen."),
"耶弗他": dict(lesson="The cost of a rash vow",
 summary="A judge who paid a heavy price for a rash vow.",
 witness="Jephthah's story is a real warning about the cost of a rash vow. Vow to God with care; do not vow rashly in the heat of emotion.",
 follow=["Though of lowly birth (a prostitute's son driven out by his brothers), still raised up by God as a deliverer, listed among the heroes of faith (Heb 11:32)","Relying on the Spirit of the LORD to go to war, greatly defeating the Ammonites"],
 caution=["Making a rash vow to God in the flesh—'whatever comes out my door first to meet me, I will offer as a burnt offering'—without thought","The result was his only daughter who met him, and a tragedy from rigidly keeping a reckless oath","Internal strife with the Ephraimites, causing 42,000 fellow Israelites to die (Judg 12:6)"],
 applications=["Be careful before vowing to God; better not to vow than to vow and not keep it, or to vow rashly (Eccl 5:5)","When emotions run high or you're eager for results, don't make major commitments","Handle disputes after victory with wisdom; don't let internal conflict cause greater loss of life"],
 prayer="Lord, let my words be few and weighed; let me pray and think before I vow. Amen."),
"巴拉": dict(lesson="Weak faith is still used by God",
 summary="A commander who worked with Deborah; for lack of faith he insisted Deborah go with him.",
 witness="Barak's life holds both an example to follow and a warning to heed. Imperfect faith is better than no faith, and God uses weak faith too.",
 follow=["Obeying God's command delivered through Deborah, leading 10,000 men up Mount Tabor against Sisera's chariots","Though his faith was weak, still stepping out in obedience, listed among the heroes of faith (Heb 11:32)","Winning completely as God said, the enemy army utterly destroyed"],
 caution=["Insufficient faith, insisting Deborah go with him before he would fight: 'if you don't go with me, I won't go'","Because of this hesitation, the glory of killing the enemy commander Sisera went to a woman, Jael (Judg 4:9)"],
 applications=["When God's command is clear, don't attach conditions—Barak's 'I'll go only if you go' cost him part of the glory","Weak faith need not pretend to be strong, but still choose to step out in obedience; God will complete the rest","Spiritual hesitation can let the blessing meant for you fall to someone else"],
 prayer="Lord, even when my faith is weak, let me still be willing to step out, and You will complete the rest. Amen."),
"罗波安": dict(lesson="Rejecting wise counsel split the kingdom",
 summary="Solomon's son, who rejected the elders' counsel and split the kingdom.",
 witness="Rehoboam's story is a real warning that rejecting wise counsel split the kingdom. Proudly rejecting wise counsel brings devastating consequences.",
 follow=["When Shishak invaded and the prophet Shemaiah rebuked him, he and the leaders once humbled themselves and confessed 'the LORD is righteous,' and God lessened the punishment (2 Chr 12:6-7)"],
 caution=["Rejecting the wise counsel of his father's veteran ministers, instead heeding his young peers, threatening 'I will discipline you with scorpions'","Responding to the people's pleas with harsh oppression, directly causing ten tribes to split off, the united kingdom torn in two","A divided heart, forsaking the law of the LORD and introducing idols (2 Chr 12:1)"],
 applications=["Major decisions need the wisdom of the older and the godly, not only voices that please you","Respond to others' reasonable pleas with humility, not harshness; harshness often brings division","When God disciplines you, humble yourself and confess in time—like Rehoboam, you can still find mercy"],
 prayer="Lord, give me a humble heart, willing to heed wise counsel. Amen."),
"古列": dict(lesson="God uses a pagan king to fulfill His plan",
 summary="Founder of the Persian Empire; after conquering Babylon he decreed that the Jews could return home and rebuild the temple—prophesied by Isaiah by name about 150 years earlier, one of the most astonishing fulfilled prophecies in the Old Testament.",
 witness="The LORD says of Cyrus: he is My shepherd, and he shall fulfill all My purpose. God named him before he was born, marking him as the executor of His plan. God's sovereignty crosses borders, religions, and time.",
 follow=["Aligning with God's timing in history, becoming a channel of His plan even without fully understanding","Treating the oppressed with magnanimity and justice, making room for God's kingdom work","Issuing decisions that set people free to turn to God"],
 caution=[],
 applications=["God named Cyrus 150 years before his birth—is your life also part of God's larger plan today?","God used a pagan king—God can use anyone, even those you think impossible","Do you have a chance today to make a decision or act that lets people turn to God more freely?","Widen your view: God's plan is bigger than any one religious group or nation"],
 prayer="Lord, You prepared Cyrus 150 years ahead to accomplish Your plan. Help me believe You had Your plan before I was born, and help me cooperate with Your work in this age. Amen."),
"所罗巴伯": dict(lesson="Rebuilding from ruins is an expression of faith",
 summary="A descendant of David who led the first group of exiles back to Jerusalem, persevering to rebuild the temple amid enemy obstruction and the people's weariness; the prophet Zechariah declared: not by might, nor by power, but by My Spirit.",
 witness="God said to him: who has despised the day of small things? And the prophet Haggai declared: be strong! be strong! and work! He persevered to the end in the hardest conditions, and the temple was finally completed. Rebuilding from ruins is faith's most concrete action.",
 follow=["Persevering in the rebuilding God entrusted amid the people's weariness and obstruction","Relying not on ability or might, but on the Spirit of God","Rising to work again, stirred by the prophets' words"],
 caution=[],
 applications=["Not by might, nor by power, but by My Spirit—what are you relying on for your rebuilding now?","Who despises the day of small things—today's tiny beginning may be the start of God's glorious great work","Is there a field of ruins in your life waiting to be rebuilt? Take a step today","When you feel weary and obstructed, the prophet's word is: be strong! and work!"],
 prayer="Lord, Zerubbabel worked amid ruins and persevered against resistance. Help me not lose hope before the ruins in my life, relying on Your Spirit rather than my own ability, and take the first step to rebuild. Amen."),
"耶何耶大": dict(lesson="A spiritual mentor shapes a nation's direction",
 summary="A high priest who secretly protected the child Joash for seven years during Athaliah's usurpation, then carefully staged a coup to restore the rightful throne, bringing religious revival to Israel; he lived 130 years and was buried among the kings.",
 witness="Chronicles records: Joash did what was right in the eyes of the LORD all the days of Jehoiada, because Jehoiada instructed him. One spiritual mentor's seven years of hidden protection and lifelong guidance can shape a nation's course.",
 follow=["Protecting the next-generation leader God had chosen, amid danger","Patiently and wisely waiting for God's timing, not acting rashly","Becoming a spiritual mentor to the young leader near him, teaching and supporting continually"],
 caution=[],
 applications=["Jehoiada protected Joash for seven hidden years—do you also have a spiritual next-generation you are protecting and nurturing?","His teaching shaped a nation—where is your spiritual influence today?","One faithful mentor can shape history—is there someone you're willing to mentor spiritually?","You can give a young person concrete spiritual guidance today"],
 prayer="Lord, Jehoiada's seven years of hidden protection changed a nation's history. Help me too, with faithfulness and patience, support those You entrust to me, becoming a guide on their spiritual path. Amen."),
"非尼哈": dict(lesson="Zeal for God's holiness",
 summary="Aaron's grandson; when Israel fell into widespread immorality with Moabite women and Baal worship, he stepped forward to stop a flagrant transgression, and so God stopped the plague and gave him a covenant of peace, a perpetual priesthood.",
 witness="God said: Phinehas' zeal was for My sake; he was zealous for Me among the Israelites, so I did not consume them in My jealousy. One person's zeal can stand in for the whole community, bearing God's anger on its behalf.",
 follow=["Not staying silent before flagrant sin, defending God's holiness by action","Becoming one who holds the standard when the community is weak","Driven by zeal for God, not by self-righteousness"],
 caution=[],
 applications=["Phinehas' zeal stopped the plague for all Israel—one person's faithfulness can affect a whole community","Is there something today you know is right but that takes courage to stand up for?","Zeal is not anger, but an inability to stand idle out of love for God's holiness","In your faith community, is there a truth you need to hold gently but firmly?"],
 prayer="Lord, Phinehas' zeal was out of love for Your holiness. Give me real zeal for the holiness You treasure, courage to stand when I must, rather than drifting with the current. Amen."),
"约瑟（耶稣父亲）": dict(lesson="Quiet obedience that protects God's plan",
 summary="Jesus' foster father, a carpenter; in the hardest situations he dreamed of an angel three times and obeyed at once—taking Mary as his wife, fleeing with the family to Egypt, returning to Nazareth—each time hearing and acting, with no record of hesitation or protest.",
 witness="Scripture never records Joseph saying a word, yet his every action was immediate obedience: he woke and did as commanded. His silence was not weakness but a deep humility and trust—in God's plan he was willing to be the unseen protector.",
 follow=["Acting at once on God's instruction, not waiting to fully understand before obeying","Quietly guarding the life God entrusted, behind the scenes, seeking no fame","Obeying God under social pressure and misunderstanding, not rushing to defend himself"],
 caution=[],
 applications=["Joseph never said a word, yet obeyed at once each time—when did you last hear and act?","He was Jesus' first protector, yet no one knows his name—is there someone or a mission you quietly guard today?","A carpenter father raised the Savior—ordinary faithfulness can nurture a historic mission","Do today the one thing God has already spoken to you that you keep postponing"],
 prayer="Lord, Joseph's life is a model of quiet obedience. Help me also act at once before Your call, not waiting for human approval, gladly guarding behind the scenes what You entrust to me. Amen."),
"撒迦利亚（约翰父亲）": dict(lesson="Restoration from unbelief to praising God",
 summary="Father of John the Baptist; struck mute for unbelief, his mouth was opened to praise God after his son's birth.",
 witness="Zechariah's life holds both an example to follow and a warning to heed. God still has mercy on unbelief and gives us a chance to change.",
 follow=["With his wife Elizabeth, both 'righteous before God, walking blamelessly in all the commandments' (Luke 1:6)","Though mute for over nine months, still obeying God, insisting on naming his son John—and his mouth was opened at once","Filled with the Spirit, singing out a prophecy of praise (the Benedictus, Luke 1:68-79)"],
 caution=["At the angel's announcement, disbelieving because of old age—'how shall I know this?'—asking for a sign, and being made mute until the child's birth","After years of priestly service, lacking faith before God's supernatural promise"],
 applications=["Long waiting and old age should not become reasons to disbelieve God's promise","In the spiritual valley of 'unable to speak,' still obey—praise will well up again","With your spouse, resolve to 'be righteous before God together,' building a united family witness"],
 prayer="Lord, in my moments of unbelief, be patient and wait for me to change. Amen."),
"马大": dict(lesson="Busy serving, forgetting the one most important thing",
 summary="The busily-serving sister, reminded by Jesus to choose the best.",
 witness="Martha's story is a real warning about being busy serving and forgetting the one most important thing. Serving God cannot replace drawing near to God.",
 follow=["Eager to host, taking the initiative to open her home to Jesus (Luke 10:38)","After Lazarus' death, making a great confession of faith: 'yes, Lord, I believe you are the Christ, the Son of God' (John 11:27)","Her service had real love; it only needed the Lord to correct its order of priorities"],
 caution=["'Worried and troubled' about many things, letting busy service crowd out the 'good portion' of sitting at the Lord's feet","Complaining to Jesus about her sister, projecting her own anxiety as blame on another"],
 applications=["Serving God cannot replace drawing near to God—first sit at the Lord's feet, then rise to work","When busy and irritable, ask: am I busy for the Lord, or so busy I forget the Lord Himself?","Don't turn your own pressure into blame on those around you; first bring your heart to the Lord"],
 prayer="Lord, let me not use busy service to cover a heart unwilling to be still before You. Amen."),
"马利亚（伯大尼）": dict(lesson="Drawing near to God is the foundation of all service",
 summary="Mary of Bethany, who chose to sit at Jesus' feet and listen while others were busy, praised for choosing the good portion that cannot be taken away; she later anointed Jesus' feet with very costly perfume, and Jesus said: wherever this gospel is preached, what she has done will be told in memory of her.",
 witness="Jesus said to busy, serving Martha: Mary has chosen the good portion, which will not be taken from her. While everyone else was serving, she chose to stop and draw near to Jesus. This was not laziness, but an accurate judgment about what matters most.",
 follow=["Still prioritizing sitting before Jesus amid busy service","Loving Jesus with all her precious time and resources, regardless of others' opinions","Making listening and nearness to God the foundation and strength of all service"],
 caution=[],
 applications=["Mary chose the good portion—where does nearness to God rank in your schedule today?","She used very costly perfume—when did you last do a 'wasteful' thing out of love for God?","Jesus said what she did would be told worldwide—one quiet act of loving God may be worth more than all service","Be still before God for 15 minutes first today, then begin your busyness"],
 prayer="Lord, Mary chose the good portion. Help me, amid busyness, to have the courage to stop and prioritize sitting at Your feet, letting nearness to You be the source of all my service. Amen."),
"拉撒路": dict(lesson="Being raised becomes a stage for God's glory",
 summary="A man of Bethany, Jesus' close friend; after dying he was buried four days, then Jesus called him out of the tomb before the crowd, and he rose—this directly triggered the religious leaders' resolve to kill Jesus, his death and resurrection becoming a fuse of the Passion.",
 witness="Jesus said: this illness is not unto death, but for the glory of God, that the Son of God may be glorified by it. Lazarus experienced death, yet became God's most direct stage of glory. God sometimes allows us to pass through the deepest valley precisely for a greater glory.",
 follow=["Still trusting Jesus' love amid the deepest suffering and shadow of death","Letting his plight become a stage for God's glory, not a prison of self-pity","Living out a witness after resurrection, so that people glorify God because of him"],
 caution=[],
 applications=["Jesus came late—sometimes God's delay is not forgetfulness, but for a greater glory","Lazarus' death was an occasion for God's glory—can your deepest pain also become a stage where God shows Himself?","He came out of the tomb still bound in grave clothes—even after resurrection you need others to unbind you; who is your companion today?","Is there a 'dead end' you've given up on that you can place again in Jesus' hands today?"],
 prayer="Lord, Lazarus' death became Your most direct stage of glory. Help me not despair in suffering, but trust that You are still working in my deepest plight to show Your glory. Amen."),
"犹大": dict(lesson="The danger of nearness to God with an unchanged heart",
 summary="One of the twelve apostles, who betrayed Jesus for thirty pieces of silver.",
 witness="Judas' story is a real warning about the danger of long nearness to God with an unchanged heart.",
 follow=[],
 caution=["Three years following closely, witnessing miracles firsthand, yet his heart never truly belonging—the most terrifying example of 'near to God, inwardly unchanged'","Keeping the money bag yet often stealing from it (John 12:6); small greed grew into the sin of betraying the Lord","Betraying Jesus for thirty pieces of silver, then in remorse going to despair and hanging himself, rather than repenting and turning back"],
 applications=["Outward nearness (meetings, service, Bible knowledge) does not equal an inner heart truly turned to God—ask God to search your heart","Don't make light of 'small' greed and small unfaithfulness—they slowly grow into deadly betrayal","After sinning, turn back like Peter, not despair like Judas—the Lord's forgiveness is always there"],
 prayer="Lord, let me not merely follow You outwardly; change my inner greed. Amen."),
"西门（行邪术）": dict(lesson="A gift cannot be bought",
 summary="A sorcerer in Samaria who, after believing, tried to buy the power of the Holy Spirit with money.",
 witness="Simon Magus' story is a real warning that a gift cannot be bought. Spiritual gifts cannot be exchanged for money or power.",
 follow=[],
 caution=["After believing and being baptized, still wanting to buy the Spirit's power with money, treating God's gift as a tradable commodity (the English word 'simony' comes from this)","His motive was to gain power and be esteemed as great, not to truly know God","Peter rebuked him sharply, 'your heart is not right before God'—showing outward baptism had not touched the inner heart"],
 applications=["Spiritual gifts and offices cannot be obtained with money, connections, or schemes—only received in humility","Examine your motive in service: to glorify God, or to be esteemed and gain power and status?","Outward religious acts (baptism, meetings) without inner true repentance are still dangerous"],
 prayer="Lord, let me not commercialize Your grace. Amen."),
"路加": dict(lesson="Professional skill in faithful service",
 summary="A Gentile physician, the most prolific New Testament author, who wrote Luke and Acts; with a doctor's precise observation he interviewed eyewitnesses and carefully recorded Jesus' life and the early church's history, the only co-worker who stayed with Paul at his final imprisonment.",
 witness="In his final letter Paul wrote: only Luke is with me. When others left out of fear or self-interest, the physician Luke remained at Paul's side. He faithfully recorded with his professional skill, and faithfully served by his companionship.",
 follow=["Offering his professional knowledge to God, becoming a channel to record and convey truth","Still accompanying his co-worker when he most needed it, not shrinking back as circumstances changed","Treating God's word seriously, with the attitude of careful observation and interview"],
 caution=[],
 applications=["Luke was a physician yet wrote the most of the New Testament—how can your profession or skill serve God's kingdom?","'Only Luke is with me'—is there a co-worker you would accompany in the hardest times?","He interviewed eyewitnesses—serious study and inquiry into God's word is the foundation of service","Do one concrete thing today serving God's kingdom with your profession"],
 prayer="Lord, Luke observed with a physician's eye, recorded with a faithful pen, and served with a companion's heart. Help me also offer my professional skill fully to You, becoming a faithful channel in Your plan. Amen."),
}
